    <div class="grid sm:grid-cols-3 gap-5 mb-8">
        {% for label, value, icon in [('Ventas registradas', total_sales|mxn, 'fa-sack-dollar'), ('Pedidos', total_orders, 'fa-receipt'), ('Clientes', total_clients, 'fa-users')] %}
        <article class="bg-slate-900 p-6 rounded-2xl border border-slate-800"><div class="flex justify-between items-center"><p class="text-slate-400 text-sm">{{ label }}</p><i class="fa-solid {{ icon }} text-sky-400"></i></div><p class="text-3xl font-bold gold mt-3">{{ value }}</p></article>
