    <div class="grid lg:grid-cols-2 gap-6">
        <article class="bg-slate-900 p-6 rounded-2xl border border-slate-800"><h2 class="font-bold text-xl mb-5">Pedidos recientes</h2><div class="overflow-x-auto"><table class="w-full text-sm min-w-[440px]"><thead class="text-slate-400 text-left"><tr><th class="pb-3">Pedido</th><th>Cliente</th><th>Total</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>{% for o in recent %}<tr class="border-t border-slate-800"><td class="py-3">#{{ o.id }}</td><td>{{ o.name }}</td><td class="gold">{{ o.total|mxn }}</td><td>{{ o.status }}</td><td class="text-slate-400">{{ o.created_at[:10] }}</td></tr>{% else %}<tr><td colspan="5" class="py-5 text-slate-500">Aún no hay pedidos.</td></tr>{% endfor %}</tbody></table></div></article>
