const brands = {{ brands | tojson }};
new Chart(document.getElementById('brandChart'), {type:'doughnut',data:{labels:brands.map(b=>b.brand),datasets:[{data:brands.map(b=>b.revenue),backgroundColor:['#e4aa24','#0879ca','#10345e','#49a6e9','#9c7a32'],borderWidth:0}]},options:{plugins:{legend:{position:'bottom',labels:{color:'#dbe5ef'}}},cutout:'64%'}});
</script>{% endif %}
{% endblock %}

const chatMessages = document.getElementById('chat-messages');
const chatForm = document.getElementById('chat-form');
const chatInput = document.getElementById('chat-input');

let history = [];

function addMessage(text, isUser) {
  const wrapper = document.createElement('div');
  wrapper.className = 'flex gap-3' + (isUser ? ' justify-end' : '');
  const avatar = isUser
    ? '<div class="w-8 h-8 rounded-full bg-sky-500/20 flex items-center justify-center text-sky-400 text-xs shrink-0 order-2"><i class="fa-solid fa-user"></i></div>'
    : '<div class="w-8 h-8 rounded-full bg-gold/20 flex items-center justify-center text-gold text-xs shrink-0"><i class="fa-solid fa-robot"></i></div>';

  const bubble = `<div class="${isUser ? 'bg-sky-600 text-white rounded-2xl rounded-tr-none' : 'bg-slate-800 text-slate-200 rounded-2xl rounded-tl-none'} px-4 py-3 max-w-[85%] text-sm whitespace-pre-line">${text}</div>`;
  wrapper.innerHTML = avatar + bubble;
  chatMessages.appendChild(wrapper);
  chatMessages.scrollTop = chatMessages.scrollHeight;
}

function addSourceBadge(source) {
  const label = source === 'meai' ? 'IA real (meai)' : 'Respuesta local';
  const color = source === 'meai' ? 'text-emerald-400 bg-emerald-400/10 border-emerald-400/30' : 'text-slate-400 bg-slate-700 border-slate-700/30';
  const el = document.createElement('div');
  el.className = 'flex gap-3';
  el.innerHTML = '<div class="w-8 h-8 shrink-0"></div><div class="flex items-center gap-1 px-2 py-1 rounded-lg border text-[10px] font-bold uppercase tracking-wider ' + color + '"><span class="w-1.5 h-1.5 rounded-full ' + (source === 'meai' ? 'bg-emerald-400' : 'bg-slate-400') + '"></span>' + label + '</div>';
  chatMessages.appendChild(el);
  chatMessages.scrollTop = chatMessages.scrollHeight;
}

function showTyping() {
  const el = document.createElement('div');
  el.id = 'typing';
  el.className = 'flex gap-3';
  el.innerHTML = '<div class="w-8 h-8 rounded-full bg-gold/20 flex items-center justify-center text-gold text-xs shrink-0"><i class="fa-solid fa-robot"></i></div><div class="bg-slate-800 rounded-2xl rounded-tl-none px-4 py-3 text-sm text-slate-400"><span class="animate-pulse">Escribiendo...</span></div>';
  chatMessages.appendChild(el);
  chatMessages.scrollTop = chatMessages.scrollHeight;
}

function removeTyping() {

  const el = document.getElementById('typing');
  if (el) el.remove();
}

async function sendMessage(text) {
  if (!text.trim()) return;
  addMessage(text, true);
  history.push({role: 'user', content: text});
  chatInput.value = '';
  showTyping();
  try {

const res = await fetch('{{ url_for("ai_chat") }}', {
  method: 'POST',
  headers: {'Content-Type': 'application/json'},
  body: JSON.stringify({message: text, history: history})
});
const data = await res.json();
removeTyping();
if (!res.ok) throw new Error(data.error || 'Error');
addMessage(data.reply, false);
history.push({role: 'assistant', content: data.reply});
if (data.source) addSourceBadge(data.source);
if (data.suggest_product) {

      const link = document.createElement('div');
      link.className = 'flex gap-3';
      link.innerHTML = '<div class="w-8 h-8 shrink-0"></div><a href="{{ url_for("products") }}" class="inline-block bg-gold text-slate-950 px-4 py-2 rounded-lg font-bold text-xs hover:opacity-90 transition">Ver productos recomendados →</a>';
      chatMessages.appendChild(link);
      chatMessages.scrollTop = chatMessages.scrollHeight;
    }
  } catch (e) {
    removeTyping();
    addMessage('Lo siento, hubo un error. Intenta de nuevo.', false);
  }
}

chatForm.addEventListener('submit', (e) => {
  e.preventDefault();
  sendMessage(chatInput.value);
});

document.querySelectorAll('.quick-btn').forEach(btn => {
  btn.addEventListener('click', () => sendMessage(btn.dataset.q));
});
</script>
{% endblock %}
